package com.dalai.llama.postprod.service.clip;

import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;

import java.nio.file.Path;
import java.util.UUID;

/**
 * A generated clip slowed to the shot with its missing frames generated by Topaz, at exactly the
 * shot's length.
 *
 * <p>Topaz slows by a whole factor, so a 4s clip for a 7s shot is slowed 2x to 8s and then brought
 * to exactly 7s with timestamps alone -- a slight speed-up, no frames invented by ffmpeg. The
 * clip is handed over through our own store, presigned for fal.ai to fetch.
 */
@Component
@RequiredArgsConstructor
public class AiSlowDown {

    static final int MAX_FACTOR = 8;

    private final ClipObjectStore objectStore;
    private final TopazEnhancer topaz;
    private final FfmpegClipProcessor ffmpeg;
    private final ShotClipVersionService clipVersions;

    public Path slow(UUID tenantId, UUID projectId, UUID requestId, Path generated, double sourceSeconds,
                     double targetSeconds, double frameRate, Path workDir) {
        String key = "conform-sources/" + requestId + ".mp4";
        objectStore.upload(key, generated);
        int factor = factor(sourceSeconds, targetSeconds);
        int fps = (int) Math.max(16, Math.min(120, Math.round(frameRate > 0 ? frameRate : 30)));
        String slowedUrl = topaz.interpolate(tenantId, projectId, objectStore.presignedUrl(objectStore.bucket(), key),
                factor, fps, sourceSeconds * factor, "conform-ai-" + requestId);
        Path slowed = workDir.resolve("slowed.mp4");
        clipVersions.fetch(slowedUrl, slowed);
        Path fitted = workDir.resolve("fitted.mp4");
        ffmpeg.fitLength(slowed, targetSeconds, fps, fitted);
        return fitted;
    }

    /** The smallest whole slow-down that reaches the target, within what Topaz accepts. */
    static int factor(double sourceSeconds, double targetSeconds) {
        return (int) Math.max(2, Math.min(MAX_FACTOR, Math.ceil(targetSeconds / sourceSeconds - 1e-9)));
    }
}
